<script setup lang="ts">defineProps<{loading:boolean;error?:Error|null;total:number;page:number;size?:number}>();defineEmits<{retry:[];page:[number]}>()</script>
<template><div class="table-container" v-loading="loading"><div v-if="error" class="error-state" role="alert"><p>{{error.message}}</p><el-button @click="$emit('retry')">重新加载</el-button></div><template v-else><div class="table-scroll"><slot /></div><div class="table-footer"><span>共 {{total}} 条记录</span><el-pagination background layout="prev, pager, next" :current-page="page" :page-size="size||20" :total="total" @current-change="$emit('page',$event)" /></div></template></div></template>
